//! Actions-only ORIGINAL bootstrap/native SDK physical IO with UID-local
//! completion. The real Router listener rejects ANY third auxiliary dial.
use super::*;
use super::super::super::super as n;
fn boot(reference:&[u8])->Vec<u8>{let properties=[RpcProperty{key:b"DomainName",value:b"account-domain.invalid"},RpcProperty{key:b"DomainId",value:b"fixture-domain"},RpcProperty{key:b"AppId",value:b"fixture-app"},RpcProperty{key:b"CC",value:b"fixture-cc"}];let mut w=Writer::new();w.boolean(true).unwrap();w.properties(&properties).unwrap();w.bytes(DESTINATION.as_bytes()).unwrap();w.bytes(b"").unwrap();w.bytes(reference).unwrap();w.bytes(b"").unwrap();w.finish().expose_to_transport().to_vec()}
async fn scenario(reference:&'static[u8],present:bool,managed:bool){
    let cert=Certificates::generate("IP:127.0.0.1");let front=TcpListener::bind((std::net::Ipv4Addr::LOCALHOST,0)).await.unwrap();let port=front.local_addr().unwrap().port();let source_listener=TcpListener::bind((std::net::Ipv4Addr::LOCALHOST,0)).await.unwrap();let destination=TcpListener::bind((std::net::Ipv4Addr::LOCALHOST,0)).await.unwrap();let source_port=source_listener.local_addr().unwrap().port();let destination_port=destination.local_addr().unwrap().port();let config=cert.server_config(&TLS13);let source_config=config.clone();let(done,finished)=oneshot::channel();
    let relay=tokio::spawn(async move{let mut joins=Vec::new();for target in [source_port,destination_port]{let(mut inbound,_)=front.accept().await.unwrap();let mut outbound=tokio::net::TcpStream::connect((std::net::Ipv4Addr::LOCALHOST,target)).await.unwrap();joins.push(tokio::spawn(async move{let _=tokio::io::copy_bidirectional(&mut inbound,&mut outbound).await;}));}finished.await.unwrap();assert!(tokio::time::timeout(Duration::from_millis(35),front.accept()).await.is_err(),"UID-local must never dial an auxiliary Router/Common path");for join in joins{join.await.unwrap();}});
    let source=tokio::spawn(async move{let mut peer=CommonPeer::open(source_listener,source_config).await;let packet=peer.next().await.unwrap();let call=decode_request(&packet[1..]).unwrap();assert_eq!(call.method,b"getAppConfigs.AccountEntry.Account");peer.send(&[reply(call.call_id,&boot(reference))]).await;peer.no_more_common().await;});
    let sdk=tokio::spawn(async move{let mut peer=CommonPeer::open(destination,config).await;let packet=peer.next().await.unwrap();let call=decode_request(&packet[1..]).unwrap();assert_eq!(call.method,b"loginSession.AccountEntry.Account");peer.send(&[reply(call.call_id,&if managed{login_result_for_account()}else{login_result()})]).await;let(_,flag)=hosting_call(&mut peer).await;assert_eq!(flag,b"4");let(_,flag)=hosting_call(&mut peer).await;assert_eq!(flag,b"3");logout_peer(peer).await;});
    if managed{
        let temp=n::account_test_support::TempDatabase::new();let manager=n::account_runtime::AccountManager::new(temp.database.clone());let created=manager.create(bootstrap_account_config(&cert.root,port),100).await.unwrap();let line=created.account.line_id.clone();manager.start(&line,1,100).await.unwrap();let before=tokio::time::timeout(Duration::from_secs(10),async{loop{let view=manager.get(&line,100).await.unwrap();if view.phase=="hosted"{break view;}tokio::task::yield_now().await;}}).await.unwrap();assert_eq!(before.user_entry_uid_local_supported,Some(present));
        let before_counts=temp.database.with_conn(|c|c.query_row("SELECT (SELECT COUNT(*) FROM sms_messages),(SELECT COUNT(*) FROM app_voice_im_messages),(SELECT COUNT(*) FROM app_voice_im_user_reads)",[],|r|Ok((r.get::<_,i64>(0)?,r.get::<_,i64>(1)?,r.get::<_,i64>(2)?))).map_err(|_|"fixture-count")).unwrap();
        for uri in ["0_1","[uid:7_9]","[uid:7_9@foreign.invalid]"]{assert_eq!(manager.lookup_user_entry(&line,1,uri,false).await.err(),Some("app_account_user_entry_consent_required"));let result=manager.lookup_user_entry(&line,1,uri,true).await;if present{let view=result.unwrap();assert_eq!(view.kind,"uid");assert_eq!(view.report,"local_uid");let body=serde_json::to_string(&view).unwrap();assert!(!body.contains("7_9")&&!body.contains("0_1")&&!body.contains("token"));}else{assert_eq!(result.err(),Some("app_account_user_entry_not_installed"));}}
        let after=manager.get(&line,100).await.unwrap();assert_eq!(after.phase,"hosted");assert_eq!(after.incoming_message_ready,before.incoming_message_ready);assert_eq!(after.incoming_call_ready,before.incoming_call_ready);let after_counts=temp.database.with_conn(|c|c.query_row("SELECT (SELECT COUNT(*) FROM sms_messages),(SELECT COUNT(*) FROM app_voice_im_messages),(SELECT COUNT(*) FROM app_voice_im_user_reads)",[],|r|Ok((r.get::<_,i64>(0)?,r.get::<_,i64>(1)?,r.get::<_,i64>(2)?))).map_err(|_|"fixture-count")).unwrap();assert_eq!(before_counts,after_counts);done.send(()).unwrap();let stopped=manager.stop(&line,1,100).await.unwrap();assert!(!stopped.io_cleanup_required);assert_eq!(manager.shutdown_all().await,0);
    }else{
        let p=RuntimeProfile::supplied_common_bootstrap(bootstrap_inputs(),bootstrap_common(&cert.root,port),bootstrap_route()).unwrap();let connector=Arc::new(LegacyDenied{calls:AtomicUsize::new(0)});let(backend,mut events)=NativeHostingBackend::new(p,connector.clone());let who=owner();backend.login(who.clone(),SdkLoginRequest{server_address:BOOTSTRAP_SDK,..request(&cert.root)}).await.unwrap();let parent=backend.original_scope(&who).unwrap();backend.pause_original_polls_for_test(&who,&parent,true).unwrap();let e=tokio::time::timeout(Duration::from_secs(4),events.recv()).await.unwrap().unwrap();assert!(matches!(e.payload,BackendEventPayload::Callback(c)if c.callback==(Callback::SdkLogin{success:true})));backend.update_status(who.clone(),STATUS_REGISTER,gateway()).await.unwrap();let attempt=backend.original(&who).unwrap();let gate=ImReceiptGate::fresh();let mut retained=None;
        for uri in [b"0_1".as_slice(),b"00_1",b"[uid:7_9]",b"[uid:7_9@foreign.invalid]"]{let a=UserEntryAction::original(who.clone(),parent.clone(),gate.clone(),Instant::now()+Duration::from_secs(3),uri).unwrap();let result=backend.resolve_user_entry(a.clone()).await;if present{assert_eq!(result.unwrap().report,"local_uid");}else{assert_eq!(result.err(),Some("app_account_user_entry_not_installed"));}retained=Some(a);assert_eq!(attempt.user_entries.active(),0);assert_eq!(attempt.user_entries.retained_bytes(),0);}
        let lease=attempt.user_entries.acquire(&who,&parent,Instant::now()+Duration::from_secs(1)).unwrap();assert_eq!(lease.id(),1,"local completion must not consume auxiliary RPC IDs");drop(lease);assert!(parent.is_open());assert_eq!(connector.calls.load(Ordering::SeqCst),0);done.send(()).unwrap();backend.update_status(who.clone(),STATUS_UNREGISTER,gateway()).await.unwrap();assert_eq!(backend.resolve_user_entry(retained.unwrap()).await.err(),Some("app_account_user_entry_scope_invalid"));backend.logout(who).await.unwrap();assert!(lock(&attempt.state).released);
    }
    tokio::time::timeout(Duration::from_secs(4),async{source.await.unwrap();sdk.await.unwrap();relay.await.unwrap();}).await.unwrap();
}
#[tokio::test]async fn uid_local_original_direct_agent_raw_uid_and_typed_uid_have_zero_aux_io_and_ids(){Box::pin(scenario(b"prefix/UserEntry:sarc -h 42.7 -p 98;",true,false)).await;}
#[tokio::test]async fn uid_local_original_adapter_locator_presence_does_not_require_a_resolver_socket(){Box::pin(scenario(b"prefix/UserEntry@adapter$locator",true,false)).await;}
#[tokio::test]async fn uid_local_absent_original_auxiliary_reference_cannot_be_invented_from_uid_syntax(){Box::pin(scenario(b"",false,false)).await;}
#[tokio::test]async fn uid_local_current_managed_account_keeps_sql_receipts_and_readiness_unchanged_with_all_joins(){Box::pin(scenario(b"prefix/UserEntry@adapter$locator",true,true)).await;}
